CREATE Procedure [Supp_PROC_Stock_ProdPieces_Delete] (@Id int,@sizeId int,@ProdPcs Int) AS  DECLARE @Coycode Int,@Ordid Int,@StyleNo Varchar(20),@StageId Int,@PartId Int,@GodId Int,@ColId Int,@StockQty Int,@SourceStageId Int,@FinalStage Char(1),@SeqNo int,@PartyId Int,@PcsStockId Int,@Rework Int,@RejectionTypeId Int ,@SqlCond as Varchar(100),@LotID int  Select @Id=@Id   Select @Coycode = CoyId From Trs_SuppProdentry Where Id=@Id   select @PartyId = 0   SELECT @Ordid = OrdId From Trs_SuppProdentry Where Id=@Id   SELECT @StyleNo = StyleNo From Trs_SuppProdentry Where Id=@Id   SELECT @LotID = IsNull(LotID,0) From Trs_SuppProdentry Where Id=@Id   SELECT @Stageid = StageId From Trs_SuppProdentry Where Id=@Id   SELECT @PartId = PartId From Trs_SuppProdentry Where Id=@Id  SELECT @GodId = GodId From Trs_SuppProdentry Where Id=@Id  SELECT @Rework = Rework From Trs_SuppProdentry Where Id=@Id   SELECT @RejectionTypeId = RejectionTypeId From Trs_SuppProdentry Where Id=@Id   Select @SeqNo = SeqNo From Trs_SuppProdentry Inner Join Supp_Prod_Sequence On Trs_SuppProdentry.OrdId=Supp_Prod_Sequence.OrdId And Trs_SuppProdentry.StyleNo=Supp_Prod_Sequence.StyleNo And Trs_SuppProdentry.StageId=Supp_Prod_Sequence.StageId Where Id=@Id  SELECT @FinalStage = Mas_Dept.SemiFinish From Trs_SuppProdentry Inner Join Mas_JobWrkComp On Trs_SuppProdentry.StageId=Mas_JobWrkComp.Id Inner Join Mas_Dept On Mas_JobWrkComp.DeptId=Mas_Dept.DeptId Where Trs_SuppProdentry.Id=@Id   SELECT @ColId = ClrId From Trs_SuppProdentry Where Id=@Id  Select @SourceStageId=SourceStageId From Trs_SuppProdentry Where Id=@Id   SELECT @StockQty = @ProdPcs  begin   DECLARE LINE_CURSOR CURSOR FOR    Select Id,SizID,ProdPcs FROM Trs_SuppProdentryQty Where ID=@Id and SizId = @SizeID  OPEN LINE_CURSOR    FETCH NEXT FROM LINE_CURSOR INTO @id,@Sizeid,@ProdPcs    WHILE @@FETCH_STATUS = 0       BEGIN     if @FinalStage='F'     Begin     UPDATE SuppPcs_StockTableQty SET StockQty=SuppPcs_StockTableQty.StockQty-@ProdPcs,ProductionQty=SuppPcs_StockTableQty.ProductionQty-@ProdPcs From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId Inner Join Trs_SuppProdentry On SuppPcs_StockTable.Coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.OrdId=Trs_SuppProdentry.OrdId And SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo  And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID And SuppPcs_StockTable.StageId=Trs_SuppProdentry.StageId And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId And SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId And SuppPcs_StockTableQty.ColId=Trs_SuppProdentry.ClrId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0  WHERE SuppPcs_StockTable.coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.Ordid=Trs_SuppProdentry.Ordid and SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID and SuppPcs_StockTable.Stageid=Trs_SuppProdentry.Stageid And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId and SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId and SuppPcs_StockTableQty.Colid=Trs_SuppProdentry.ClrId and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 and Partyid=@Partyid And Trs_SuppProdentry.Id=@Id  End  if @FinalStage='S'  Begin    UPDATE SuppPcs_StockTableQty SET StockQty=SuppPcs_StockTableQty.StockQty-@ProdPcs,ProductionQty=SuppPcs_StockTableQty.ProductionQty-@ProdPcs From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId Inner Join Trs_SuppProdentry On SuppPcs_StockTable.Coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.OrdId=Trs_SuppProdentry.OrdId And SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID And SuppPcs_StockTable.StageId=Trs_SuppProdentry.StageId And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId And SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId And SuppPcs_StockTableQty.ColId=Trs_SuppProdentry.ClrId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 WHERE SuppPcs_StockTable.coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.Ordid=Trs_SuppProdentry.Ordid and SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID and SuppPcs_StockTable.Stageid=Trs_SuppProdentry.Stageid And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId and SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId and SuppPcs_StockTableQty.Colid=Trs_SuppProdentry.ClrId and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 and Partyid=@Partyid And Trs_SuppProdentry.Id=@Id  End  If @SourceStageid<>0 And @StageId<>1 And @FinalStage='S' And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece' Begin   If EXISTS (select * from SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotID = @LotID and Stageid=@SourceStageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId)    begin   Select @PcsStockId=PcsStockId From SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotID = @LotID  and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId   If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo And LotId=@LotID and Stageid=@SourceStageid and PartId=@PartId and GodId=@GodId and  PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)     Begin   UPDATE SuppPcs_StockTableQty SET StockQty=SuppPcs_StockTableQty.StockQty+@ProdPcs From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId Inner Join Trs_SuppProdentry On SuppPcs_StockTable.Coycode=Trs_SuppProdentry.CoyId And  SuppPcs_StockTable.OrdId=Trs_SuppProdentry.OrdId And SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId And SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId And SuppPcs_StockTableQty.ColId=Trs_SuppProdentry.ClrId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End And SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End WHERE SuppPcs_StockTable.coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.Ordid=Trs_SuppProdentry.Ordid and SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID And SuppPcs_StockTable.PartId=Trs_SuppProdentry.PartId and SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId and SuppPcs_StockTableQty.Colid=Trs_SuppProdentry.ClrId and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End and Partyid=@Partyid And SuppPcs_StockTable.StageId=@SourceStageId And Trs_SuppProdentry.Id=@Id End  Else Begin INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End) End  End  Else begin Select @PcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable INSERT INTO SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotID) VALUES (@Coycode,@Ordid,@StyleNo,@SourceStageid,@PartId,@SeqNo,@GodId,@PcsStockId,@PartyId,@LotID) INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)  End End If  @StageId<>1 And @FinalStage='F' And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'  Begin   If EXISTS (select * from SuppPcs_StockTable INNER JOIN Trs_Supp_Prodentry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_Prodentry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_Prodentry_SourceStageDtl.SourceStageId  where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId = @LotId and GodId=@GodId and PartyId=@PartyId)   begin  Select @PcsStockId=PcsStockId From SuppPcs_StockTable INNER JOIN Trs_Supp_Prodentry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_Prodentry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_Prodentry_SourceStageDtl.SourceStageId  where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and  GodId=@GodId and PartyId=@PartyId and Trs_Supp_Prodentry_SourceStageDtl.ID  = @ID If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId INNER JOIN Trs_Supp_Prodentry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_Prodentry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_Prodentry_SourceStageDtl.SourceStageId  where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId = @LotID  and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End) Begin  UPDATE SuppPcs_StockTableQty SET StockQty=SuppPcs_StockTableQty.StockQty+@ProdPcs From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId Inner Join Trs_SuppProdentry On SuppPcs_StockTable.Coycode=Trs_SuppProdentry.CoyId And  SuppPcs_StockTable.OrdId=Trs_SuppProdentry.OrdId And SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID And SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId And SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End INNER JOIN Trs_Supp_Prodentry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_Prodentry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_Prodentry_SourceStageDtl.SourceStageId  and Trs_Supp_Prodentry_SourceStageDtl.Id = @Id WHERE SuppPcs_StockTable.coycode=Trs_SuppProdentry.CoyId And SuppPcs_StockTable.Ordid=Trs_SuppProdentry.Ordid and SuppPcs_StockTable.StyleNo=Trs_SuppProdentry.StyleNo And SuppPcs_StockTable.LotId=Trs_SuppProdentry.LotID and SuppPcs_StockTable.GodId=Trs_SuppProdentry.GodId and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End and Partyid=@Partyid  And Trs_SuppProdentry.Id=@Id and Trs_Supp_Prodentry_SourceStageDtl.Id = @Id End Else Begin INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End) End End  Else  begin  Select @PcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable   INSERT INTO SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotID) VALUES (@Coycode,@Ordid,@StyleNo,@SourceStageid,@PartId,@SeqNo,@GodId,@PcsStockId,@PartyId,@LotID) INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End) End End   FETCH NEXT FROM LINE_CURSOR INTO @id,@Sizeid,@ProdPcs   END   CLOSE LINE_CURSOR     DEALLOCATE LINE_CURSOR    SET NOCOUNT OFF  END 
 


